INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DisplayPort dasselbe wie HDMI?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Standards"}, {"text": "Ja", "correct": false, "because": "Verschiedene Anschlüsse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat DisplayPort?', 3, '[{"text": "Video- und Audioübertragung", "correct": true, "because": "Monitoranbindung"}, {"text": "Datenbackup", "correct": false, "because": "Nicht Speicher"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Kein Ethernet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features bietet DisplayPort?', 5, '[{"text": "Hohe Auflösung", "correct": true, "because": "Bis 8K"}, {"text": "Multi-Monitor-Unterstützung", "correct": true, "because": "Daisy-Chaining"}, {"text": "Datenverschlüsselung", "correct": false, "because": "HDCP optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DisplayPort unterstützt 4K. b) Es ist mit HDMI kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adapter nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines DisplayPort-Kabels?', 4, '[{"text": "Version", "correct": false, "because": "Bestimmt Bandbreite"}, {"text": "Länge", "correct": false, "because": "Beeinflusst Signal"}, {"text": "Kabelgewicht", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DisplayPort nur Video überträgt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Audio"}, {"text": "Ja", "correct": false, "because": "Video und Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Version von DisplayPort unterstützt 8K?', 3, '[{"text": "2.0", "correct": true, "because": "Hohe Bandbreite"}, {"text": "1.2", "correct": false, "because": "Max 4K"}, {"text": "1.0", "correct": false, "because": "Älterer Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat DisplayPort?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Für hohe Auflösungen"}, {"text": "Daisy-Chaining", "correct": true, "because": "Mehrere Monitore"}, {"text": "Permanente Stromversorgung", "correct": false, "because": "Nur Signal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DisplayPort ist für Monitore. b) Es überträgt Netzwerkdaten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Netzwerk"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DisplayPort?', 4, '[{"text": "Kompatible Geräte", "correct": false, "because": "Notwendig"}, {"text": "Kabel", "correct": false, "because": "Verbindung erforderlich"}, {"text": "Externer Akku", "correct": true, "because": "Strom über Gerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DisplayPort abwärtskompatibel?', 2, '[{"text": "Ja", "correct": true, "because": "Ältere Versionen laufen"}, {"text": "Nein", "correct": false, "because": "Kompatibilität gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen DisplayPort?', 4, '[{"text": "Monitore", "correct": true, "because": "Primäre Nutzung"}, {"text": "PCs", "correct": true, "because": "Videoausgang"}, {"text": "Drucker", "correct": false, "because": "Keine Videoübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DisplayPort nur für PCs ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Laptops, Konsolen"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DisplayPort?', 3, '[{"text": "Version", "correct": true, "because": "Bestimmt Auflösung"}, {"text": "Kabeldesign", "correct": false, "because": "Sekundär"}, {"text": "Preis", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DisplayPort überträgt Audio. b) Es ist nur für 1080p.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bis 8K möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zu HDMI?', 5, '[{"text": "Daisy-Chaining", "correct": true, "because": "Nur DisplayPort"}, {"text": "Höhere Bandbreite", "correct": true, "because": "Neuere Versionen"}, {"text": "Kleinere Stecker", "correct": false, "because": "Ähnliche Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DisplayPort unwichtig?', 3, '[{"text": "Auflösungsunterstützung", "correct": false, "because": "Kernmerkmal"}, {"text": "Kompatibilität", "correct": false, "because": "Entscheidend"}, {"text": "Kabelgewicht", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht DisplayPort einen Adapter für HDMI?', 3, '[{"text": "Ja", "correct": true, "because": "Unterschiedliche Anschlüsse"}, {"text": "Nein", "correct": false, "because": "Adapter nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DisplayPort Strom liefert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Signalübertragung"}, {"text": "Ja", "correct": false, "because": "Keine Stromversorgung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht DisplayPort besonders?', 4, '[{"text": "Multi-Stream", "correct": true, "because": "Mehrere Monitore"}, {"text": "Datenbackup", "correct": false, "because": "Nicht Speicher"}, {"text": "Netzwerkfähigkeit", "correct": false, "because": "Kein Ethernet"}]');
